  match r, ph with
  | 1, 0 => farm1_0_1RB1RB_1RC0LD_1LB1RA_0RC1LD
  | _, _ => farm1_0_1RB1RB_1RC0LD_1LB1RA_0RC1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RB_1RC0LD_1LB1RA_0RC1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RB_1RC0LD_1LB1RA_0RC1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

