    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1RC1LB_0LB1RA_0RC0LA | exact ok_iarm0_1_1RB1RD_1RC1LB_0LB1RA_0RC0LA]. }
    exfalso; lia.
